// Project-owned Rust surface analyzer. Requires Cargo + serde/serde_json (vendor for air-gap).
use serde::{Deserialize,Serialize};
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path,process::Command};
#[derive(Deserialize)]struct Req{schema:u32,kind:String,stub_id:String,root:String,base_commit:Option<String>,head_commit:String}
#[derive(Serialize)]struct Change{path:String,symbol:String,change:String,before:String,after:String}
#[derive(Serialize)]struct Resp{schema:u32,kind:String,stub_id:String,base_commit:Option<String>,head_commit:String,changes:Vec<Change>}
fn git(root:&str,args:&[&str],optional:bool)->Result<String,String>{let x=Command::new("git").arg("-C").arg(root).args(args).output().map_err(|e|e.to_string())?;if !x.status.success(){if optional {return Ok(String::new());}return Err(String::from_utf8_lossy(&x.stderr).to_string());}Ok(String::from_utf8_lossy(&x.stdout).into())}
fn surface(text:&str)->BTreeMap<String,String>{let mut out=BTreeMap::new();for line in text.lines(){let t=line.trim();if !t.starts_with("pub ")&&!t.starts_with("pub("){continue;}let clean=t.replace('\t'," ");let words:Vec<&str>=clean.split_whitespace().collect();let kw=words.iter().position(|w|matches!(*w,"fn"|"struct"|"enum"|"trait"|"type"|"const"));if let Some(i)=kw {if let Some(name)=words.get(i+1){let n=name.split(|c:char|!c.is_ascii_alphanumeric()&&c!='_').next().unwrap_or("");if !n.is_empty(){out.insert(format!("pub:{}",n),t.chars().take(220).collect());}}}}out}
fn run()->Result<(),String>{let args:Vec<String>=std::env::args().collect();if args.len()!=3{return Err("usage: rust stub REQUEST OUTPUT".into());}let r:Req=serde_json::from_str(&fs::read_to_string(&args[1]).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if r.schema!=1||r.kind!="surface-analysis"||r.base_commit.as_deref().unwrap_or("").is_empty(){return Err("invalid request".into());}let base=r.base_commit.as_deref().unwrap();let names=git(&r.root,&["diff","--name-only","--diff-filter=ACDMRT",base,&r.head_commit,"--"],false)?;if names.lines().count()>500{return Err("too many paths".into());}let mut changes=Vec::new();for path in names.lines(){if !path.ends_with(".rs")||path.starts_with('/')||path.split('/').any(|p|p=="..") {continue;}let prior=git(&r.root,&["show",&format!("{}:{}",base,path)],true)?;let full=Path::new(&r.root).join(path);if full.is_symlink(){return Err("symlink refused".into());}let current=if full.is_file(){fs::read_to_string(full).map_err(|e|e.to_string())?}else{String::new()};let before=surface(&prior);let after=surface(&current);let keys:BTreeSet<_>=before.keys().chain(after.keys()).collect();for symbol in keys{if before.get(symbol)==after.get(symbol){continue;}let a=before.get(symbol).cloned().unwrap_or_default();let b=after.get(symbol).cloned().unwrap_or_default();let change=if !before.contains_key(symbol){"added"}else if !after.contains_key(symbol){"removed"}else{"changed"};changes.push(Change{path:path.to_owned(),symbol:symbol.clone(),change:change.into(),before:a,after:b});}}let resp=Resp{schema:1,kind:r.kind,stub_id:r.stub_id,base_commit:r.base_commit,head_commit:r.head_commit,changes};fs::write(&args[2],format!("{}\n",serde_json::to_string(&resp).map_err(|e|e.to_string())?)).map_err(|e|e.to_string())}
fn main(){if let Err(e)=run(){eprintln!("rust stub: {}",e);std::process::exit(2)}}
